content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_am_open",
 "name": "Coldwater A.M.: cold open",
 "set": "set_ksab_morning",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Host"
  },
  "b": {
   "mark": "b",
   "label": "Co-host"
  }
 },
 "wallText": "COLDWATER A.M.",
 "wallSub": "{day} · {time} · {temp}° · rise and shine",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "cam1",
    "frame": "wide",
    "on": [],
    "move": "push",
    "cut": "dissolve"
   },
   "hold": 2.4,
   "gfx": [
    {
     "kind": "full",
     "title": "Coldwater A.M.",
     "sub": "Good morning · {day}, {time}",
     "at": 0,
     "for": 2.2
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam2",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Good morning, Coldwater! It's {time}, it's {temp} degrees, and you're up!",
     "Morning, everybody. {day}, {time}, {temp} degrees out there."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{a.name}",
     "sub": "Your host · Coldwater A.M.",
     "at": 0.4,
     "for": 4
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "b"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "b",
    "lines": [
     "Feels like {feels}. I checked twice.",
     "And it's {weather}, so bring a coat."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{b.name}",
     "sub": "With · Coldwater A.M.",
     "at": 0.4,
     "for": 4
    },
    {
     "kind": "ticker",
     "text": "TODAY {weather} · HIGH {hi}° LOW {lo}° · TOMORROW {tomorrow}",
     "at": 0.2,
     "for": 0
    }
   ]
  }
 ]
}
